pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    function testFuzz_property(address from, uint256 n, uint256 seed) public {
        n = bound(n, 1, 8);
        address[] memory tos = new address[](n);
        uint256[] memory vals = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encode(seed, i)))) | 1);
            vals[i] = uint256(keccak256(abi.encode(seed, i, "v"))) % 1e30;
        }
        TransferFromRecorder rec = new TransferFromRecorder();
        bool ok = c.transfer(from, address(rec), tos, vals);
        assertTrue(ok && rec.count() == n && rec.lastFrom() == from && rec.lastTo() == tos[n - 1] && rec.lastValue() == vals[n - 1]);
    }
}

contract TransferFromRecorder {
    uint256 public count;
    address public lastFrom;
    address public lastTo;
    uint256 public lastValue;

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        count++;
        lastFrom = from;
        lastTo = to;
        lastValue = value;
        return true;
    }

    fallback() external payable { revert(); }
    receive() external payable { revert(); }
}
